"""The daily math drill: small problems generated by CODE, with answers computed by code.

WHY CODE, NOT AN LLM. A language model asked for "a worked softmax example" will occasionally get the arithmetic wrong,
and a drill with a wrong answer key teaches the wrong thing with full confidence. Each generator below draws random
small integers, builds the problem, and computes the exact answer, so the key is always right, every day's drill is
new, and grading is a numeric comparison. The LLM is not involved at all (zero cost).

WHAT IT TRAINS. The math an ML engineer uses weekly: dot products and norms (embeddings), matrix shapes and costs
(every model), derivatives and the chain rule (backprop), probability (Bayes, expectation, entropy, KL: losses and
evaluation), and the ML-specific formulas built on them (softmax, cross-entropy, precision/recall, attention scores,
parameter counts). Each topic is a ~2-minute problem; five a day is ~15 minutes.

DETERMINISM. Problem i of day D is generated from seed sha256(f"{D}:{i}:{topic}"), so a page refresh shows the same
problems and the stored answers stay meaningful.
"""
from __future__ import annotations

import hashlib
import math
import random
import re
from collections.abc import Callable
from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True)
class Problem:
    topic: str
    prompt: str  # markdown + LaTeX
    answer: float
    tol: float
    solution: str  # markdown + LaTeX, shown after the first attempt
    hint: str


def _vec(rng, n, lo=-4, hi=5, nonzero=False):
    while True:
        v = [rng.randint(lo, hi) for _ in range(n)]
        if not nonzero or any(v):
            return v


def _fmt(v) -> str:
    return "(" + ", ".join(str(x) for x in v) + ")"


def _r(x: float, d: int = 3) -> str:
    return f"{x:.{d}f}"


# ------------------------------------------------------------------------------------------------ linear algebra
def dot_product(rng):
    a, b = _vec(rng, 3), _vec(rng, 3)
    ans = sum(x * y for x, y in zip(a, b))
    terms = " + ".join(f"({x})({y})" for x, y in zip(a, b))
    return Problem("dot-product", f"Compute the dot product $a \\cdot b$ for $a = {_fmt(a)}$ and $b = {_fmt(b)}$.", ans, 1e-6,
                   f"$a \\cdot b = \\sum_i a_i b_i = {terms} = {ans}$. The dot product is the workhorse of embeddings: "
                   "it is large when vectors point the same way.", "Multiply component-wise, then add.")


def vector_norm(rng):
    a = _vec(rng, 3, nonzero=True)
    sq = sum(x * x for x in a)
    ans = math.sqrt(sq)
    return Problem("vector-norm", f"Compute the Euclidean (L2) norm $\\|a\\|_2$ of $a = {_fmt(a)}$. Round to 3 decimals.", ans, 2e-3,
                   f"$\\|a\\|_2 = \\sqrt{{\\sum_i a_i^2}} = \\sqrt{{{sq}}} \\approx {_r(ans)}$.", "Square each component, sum, take the square root.")


def cosine_similarity(rng):
    a, b = _vec(rng, 3, nonzero=True), _vec(rng, 3, nonzero=True)
    dot = sum(x * y for x, y in zip(a, b))
    na, nb = math.sqrt(sum(x * x for x in a)), math.sqrt(sum(y * y for y in b))
    ans = dot / (na * nb)
    return Problem("cosine-similarity", f"Compute the cosine similarity of $a = {_fmt(a)}$ and $b = {_fmt(b)}$. Round to 3 decimals.", ans, 2e-3,
                   f"$\\cos\\theta = \\frac{{a\\cdot b}}{{\\|a\\|\\|b\\|}} = \\frac{{{dot}}}{{{_r(na)} \\times {_r(nb)}}} \\approx {_r(ans)}$. "
                   "It ignores length and keeps only direction, which is why it is the default for text embeddings.",
                   "Dot product divided by the product of the two norms.")


def matmul_entry(rng):
    A = [_vec(rng, 3, -3, 4) for _ in range(2)]
    B = [_vec(rng, 2, -3, 4) for _ in range(3)]
    i, j = rng.randint(1, 2), rng.randint(1, 2)
    row, col = A[i - 1], [B[k][j - 1] for k in range(3)]
    ans = sum(x * y for x, y in zip(row, col))
    tex = lambda M: "\\begin{bmatrix}" + " \\\\ ".join(" & ".join(str(x) for x in r) for r in M) + "\\end{bmatrix}"
    return Problem("matmul-entry", f"Let $A = {tex(A)}$ ($2\\times 3$) and $B = {tex(B)}$ ($3\\times 2$). Compute the entry $(AB)_{{{i}{j}}}$.",
                   ans, 1e-6, f"$(AB)_{{{i}{j}}}$ is row {i} of $A$ dotted with column {j} of $B$: ${_fmt(row)} \\cdot {_fmt(col)} = {ans}$.",
                   f"Take row {i} of A and column {j} of B.")


def matmul_cost(rng):
    m, n, p = rng.choice([2, 4, 8, 16, 32]), rng.choice([3, 5, 10, 64]), rng.choice([2, 6, 12, 128])
    ans = m * n * p
    return Problem("matmul-cost", f"$A$ is ${m}\\times{n}$ and $B$ is ${n}\\times{p}$. How many scalar multiplications does the naive product $AB$ take?",
                   ans, 1e-6, f"$AB$ is ${m}\\times{p}$; each of its ${m * p}$ entries is a dot product of length ${n}$: ${m}\\cdot{n}\\cdot{p} = {ans}$. "
                   "This $mnp$ cost is why layer width dominates compute.", "Output entries times the length of each dot product.")


def determinant_2x2(rng):
    a, b, c, d = (rng.randint(-6, 7) for _ in range(4))
    ans = a * d - b * c
    return Problem("determinant", f"Compute $\\det\\begin{{bmatrix}}{a} & {b} \\\\ {c} & {d}\\end{{bmatrix}}$.", ans, 1e-6,
                   f"$ad - bc = ({a})({d}) - ({b})({c}) = {ans}$. Zero would mean the matrix squashes the plane onto a line (not invertible).",
                   "ad - bc.")


def eigen_symmetric(rng):
    a, b = rng.randint(1, 7), rng.randint(1, 5)
    ans = a + b
    return Problem("eigenvalues", f"The symmetric matrix $\\begin{{bmatrix}}{a} & {b} \\\\ {b} & {a}\\end{{bmatrix}}$ has two eigenvalues. What is the LARGER one?",
                   ans, 1e-6, f"Try $v=(1,1)$: $Mv = ({a + b}, {a + b}) = {a + b}\\,v$, so $\\lambda_1 = {a + b}$; $v=(1,-1)$ gives $\\lambda_2 = {a - b}$. "
                   "Eigenvectors are the directions a matrix only stretches; PCA keeps the largest ones.", "Try the vectors (1, 1) and (1, -1).")


# ------------------------------------------------------------------------------------------------ calculus
def derivative_poly(rng):
    a, b, c, x0 = rng.randint(-3, 4), rng.randint(-4, 5), rng.randint(-5, 6), rng.randint(-2, 3)
    ans = 3 * a * x0 ** 2 + 2 * b * x0 + c
    return Problem("derivative", f"Let $f(x) = {a}x^3 + {b}x^2 + {c}x$. Compute $f'({x0})$.", ans, 1e-6,
                   f"$f'(x) = {3 * a}x^2 + {2 * b}x + {c}$, so $f'({x0}) = {3 * a}({x0})^2 + {2 * b}({x0}) + {c} = {ans}$.",
                   "Power rule: d/dx x^n = n x^(n-1).")


def chain_rule(rng):
    a, b, n, x0 = rng.randint(1, 4), rng.randint(-3, 4), rng.randint(2, 4), rng.randint(-1, 2)
    ans = n * a * (a * x0 + b) ** (n - 1)
    return Problem("chain-rule", f"Let $f(x) = ({a}x + {b})^{n}$. Compute $f'({x0})$.", ans, 1e-6,
                   f"Outer $u^{n}$, inner $u = {a}x + {b}$: $f'(x) = {n}u^{n - 1}\\cdot {a}$. At $x={x0}$, $u = {a * x0 + b}$, so "
                   f"$f'({x0}) = {n}\\cdot({a * x0 + b})^{n - 1}\\cdot{a} = {ans}$. Backpropagation is this rule applied layer by layer.",
                   "Derivative of the outside, times the derivative of the inside.")


def partial_derivative(rng):
    a, b, x0, y0 = rng.randint(1, 4), rng.randint(-3, 4), rng.randint(-2, 3), rng.randint(-2, 3)
    ans = 2 * a * x0 * y0
    return Problem("partial-derivative", f"Let $f(x, y) = {a}x^2 y + {b}y^2$. Compute $\\frac{{\\partial f}}{{\\partial x}}$ at $(x, y) = ({x0}, {y0})$.",
                   ans, 1e-6, f"Treat $y$ as a constant: $\\partial f/\\partial x = {2 * a}xy$; at $({x0},{y0})$ that is ${ans}$. "
                   "A gradient is just the vector of these partials.", "Hold y fixed and differentiate in x.")


def sigmoid_derivative(rng):
    x0 = rng.choice([0, 1, -1, 2, -2, 0.5])
    s = 1 / (1 + math.exp(-x0))
    ans = s * (1 - s)
    return Problem("sigmoid", f"For $\\sigma(x) = \\frac{{1}}{{1+e^{{-x}}}}$, compute $\\sigma'({x0})$. Round to 3 decimals.", ans, 2e-3,
                   f"$\\sigma'(x) = \\sigma(x)(1-\\sigma(x))$; $\\sigma({x0}) \\approx {_r(s, 4)}$, so $\\sigma'({x0}) \\approx {_r(ans, 4)}$. "
                   "Its maximum is 0.25 at 0, one reason deep sigmoid networks suffer vanishing gradients.", "Use sigma'(x) = sigma(x)(1 - sigma(x)).")


def gradient_descent_step(rng):
    k, t, w0 = rng.randint(1, 3), rng.randint(-3, 4), rng.randint(-3, 6)
    lr = rng.choice([0.1, 0.05, 0.25])
    g = 2 * k * (w0 - t)
    ans = w0 - lr * g
    return Problem("gradient-descent", f"Loss $L(w) = {k}(w - {t})^2$, current $w_0 = {w0}$, learning rate $\\eta = {lr}$. What is $w_1$ after one gradient-descent step?",
                   ans, 1e-6, f"$L'(w) = {2 * k}(w - {t})$, so $L'({w0}) = {g}$ and $w_1 = w_0 - \\eta L'(w_0) = {w0} - {lr}\\cdot{g} = {ans:g}$. "
                   f"The step moves toward the minimum at $w={t}$.", "w1 = w0 - lr * dL/dw at w0.")


# ------------------------------------------------------------------------------------------------ probability
def bayes_rule(rng):
    prev = rng.choice([0.01, 0.02, 0.05, 0.1])
    sens = rng.choice([0.9, 0.95, 0.99])
    fpr = rng.choice([0.05, 0.1, 0.02])
    ans = sens * prev / (sens * prev + fpr * (1 - prev))
    return Problem("bayes-rule", f"A classifier flags spam. {prev:.0%} of emails are spam. It flags {sens:.0%} of spam and {fpr:.0%} of non-spam. "
                   "Given an email is flagged, what is the probability it is spam? Round to 3 decimals.", ans, 2e-3,
                   f"$P(S\\mid +) = \\frac{{P(+\\mid S)P(S)}}{{P(+\\mid S)P(S) + P(+\\mid \\neg S)P(\\neg S)}} = "
                   f"\\frac{{{sens}\\cdot{prev}}}{{{sens}\\cdot{prev} + {fpr}\\cdot{1 - prev:g}}} \\approx {_r(ans)}$. "
                   "With a rare positive class, even a good classifier's flags are often wrong: this is base-rate neglect, and why precision matters.",
                   "Bayes: P(S|+) = P(+|S)P(S) / P(+).")


def _dist(rng):
    vals = sorted(rng.sample(range(-3, 8), 3))
    probs = rng.choice([[0.2, 0.5, 0.3], [0.25, 0.25, 0.5], [0.1, 0.6, 0.3], [0.5, 0.3, 0.2]])
    return vals, probs


def expectation(rng):
    vals, probs = _dist(rng)
    ans = sum(v * p for v, p in zip(vals, probs))
    table = ", ".join(f"$P(X={v}) = {p}$" for v, p in zip(vals, probs))
    return Problem("expectation", f"A random variable has {table}. Compute $\\mathbb{{E}}[X]$.", ans, 1e-6,
                   f"$\\mathbb{{E}}[X] = \\sum_x x\\,P(X=x) = {' + '.join(f'({v})({p})' for v, p in zip(vals, probs))} = {ans:g}$.",
                   "Weight each value by its probability and add.")


def variance(rng):
    vals, probs = _dist(rng)
    mu = sum(v * p for v, p in zip(vals, probs))
    ans = sum(p * (v - mu) ** 2 for v, p in zip(vals, probs))
    table = ", ".join(f"$P(X={v}) = {p}$" for v, p in zip(vals, probs))
    return Problem("variance", f"A random variable has {table}. Compute $\\mathrm{{Var}}(X)$. Round to 3 decimals.", ans, 2e-3,
                   f"$\\mu = {mu:g}$; $\\mathrm{{Var}}(X) = \\sum_x P(x)(x-\\mu)^2 \\approx {_r(ans)}$ "
                   "(equivalently $\\mathbb{E}[X^2] - \\mu^2$).", "First the mean, then the probability-weighted squared distance from it.")


def entropy_bits(rng):
    probs = rng.choice([[0.5, 0.5], [0.5, 0.25, 0.25], [0.25, 0.25, 0.25, 0.25], [0.5, 0.25, 0.125, 0.125], [1.0]])
    ans = -sum(p * math.log2(p) for p in probs)
    terms = " + ".join(f"{p}" + r"\cdot" + f"{-math.log2(p):g}" for p in probs)
    return Problem("entropy", f"Compute the entropy in bits, $H = -\\sum_i p_i \\log_2 p_i$, of the distribution ${_fmt(probs)}$.", ans, 1e-3,
                   f"$H = {terms} = {ans:g}$ bits: the average number of yes/no questions "
                   "needed to identify the outcome. Cross-entropy loss is built on the same quantity.", "-log2 of 1/2 is 1, of 1/4 is 2, of 1/8 is 3.")


def kl_divergence(rng):
    p = rng.choice([[0.5, 0.5], [0.7, 0.3], [0.9, 0.1], [0.6, 0.4]])
    q = rng.choice([[0.5, 0.5], [0.8, 0.2], [0.3, 0.7], [0.4, 0.6]])
    ans = sum(pi * math.log(pi / qi) for pi, qi in zip(p, q))
    terms = " + ".join(f"{pi}" + r"\ln" + f"({pi}/{qi})" for pi, qi in zip(p, q))
    return Problem("kl-divergence", f"Compute $D_{{KL}}(P\\,\\|\\,Q) = \\sum_i p_i \\ln\\frac{{p_i}}{{q_i}}$ (natural log) for $P = {_fmt(p)}$, $Q = {_fmt(q)}$. Round to 3 decimals.",
                   ans, 2e-3, f"$D_{{KL}} = {terms} \\approx {_r(ans)}$ nats. "
                   "It is zero only when $P = Q$ and is not symmetric; it appears in RLHF/DPO as the penalty for drifting from the base model.",
                   "Sum p_i * ln(p_i / q_i).")


def conditional_probability(rng):
    a, b, c, d = (rng.randint(5, 60) for _ in range(4))
    ans = a / (a + c)
    return Problem("conditional-probability",
                   "A test set, counted by prediction and truth:\n\n| | truth: positive | truth: negative |\n|---|---|---|\n"
                   f"| predicted positive | {a} | {b} |\n| predicted negative | {c} | {d} |\n\n"
                   "What is $P(\\text{predicted positive} \\mid \\text{truth positive})$ (the recall)? Round to 3 decimals.", ans, 2e-3,
                   f"Condition on the truth-positive column: ${a} / ({a} + {c}) \\approx {_r(ans)}$.", "Restrict to the column you condition on.")


# ------------------------------------------------------------------------------------------------ ML formulas
def softmax(rng):
    z = [rng.randint(-2, 3) for _ in range(3)]
    i = rng.randint(1, 3)
    ex = [math.exp(v) for v in z]
    ans = ex[i - 1] / sum(ex)
    return Problem("softmax", f"Logits $z = {_fmt(z)}$. Compute $\\mathrm{{softmax}}(z)_{i}$. Round to 3 decimals.", ans, 2e-3,
                   f"$\\mathrm{{softmax}}(z)_i = e^{{z_i}} / \\sum_j e^{{z_j}} = e^{{{z[i - 1]}}} / ({' + '.join(f'e^{{{v}}}' for v in z)}) \\approx {_r(ans)}$. "
                   "Subtracting $\\max z$ first gives the same result and avoids overflow.", "Exponentiate, then normalise to sum to 1.")


def cross_entropy(rng):
    probs = rng.choice([[0.7, 0.2, 0.1], [0.5, 0.3, 0.2], [0.1, 0.8, 0.1], [0.25, 0.25, 0.5]])
    y = rng.randint(1, 3)
    ans = -math.log(probs[y - 1])
    return Problem("cross-entropy", f"A classifier outputs probabilities ${_fmt(probs)}$ over 3 classes; the true class is {y}. "
                   "Compute the cross-entropy loss (natural log). Round to 3 decimals.", ans, 2e-3,
                   f"With a one-hot target, cross-entropy is $-\\ln p_{{y}} = -\\ln {probs[y - 1]} \\approx {_r(ans)}$. "
                   "Confident wrong answers are punished without bound as $p_y \\to 0$.", "Only the true class's probability matters.")


def mse(rng):
    y = [rng.randint(-3, 6) for _ in range(4)]
    yh = [v + rng.randint(-2, 2) for v in y]
    ans = sum((a - b) ** 2 for a, b in zip(y, yh)) / 4
    return Problem("mse", f"Targets $y = {_fmt(y)}$, predictions $\\hat y = {_fmt(yh)}$. Compute the mean squared error.", ans, 1e-6,
                   f"Squared errors: {_fmt([(a - b) ** 2 for a, b in zip(y, yh)])}; mean $= {ans:g}$.", "Average of (y - y_hat)^2.")


def precision_recall_f1(rng):
    tp, fp, fn = rng.randint(5, 50), rng.randint(1, 30), rng.randint(1, 30)
    which = rng.choice(["precision", "recall", "F1"])
    p, r = tp / (tp + fp), tp / (tp + fn)
    ans = {"precision": p, "recall": r, "F1": 2 * p * r / (p + r)}[which]
    return Problem("precision-recall", f"A retriever returns results with TP = {tp}, FP = {fp}, FN = {fn}. Compute the **{which}**. Round to 3 decimals.",
                   ans, 2e-3, f"precision $= TP/(TP+FP) = {_r(p)}$, recall $= TP/(TP+FN) = {_r(r)}$, F1 $= 2PR/(P+R) = {_r(2 * p * r / (p + r))}$.",
                   "Precision: of what you returned. Recall: of what you should have returned.")


def attention_score(rng):
    q, k = _vec(rng, 4, -2, 3), _vec(rng, 4, -2, 3)
    dot = sum(a * b for a, b in zip(q, k))
    ans = dot / 2.0
    return Problem("attention-score", f"In scaled dot-product attention with $d_k = 4$, compute the pre-softmax score $\\frac{{q\\cdot k}}{{\\sqrt{{d_k}}}}$ for "
                   f"$q = {_fmt(q)}$, $k = {_fmt(k)}$.", ans, 1e-6,
                   f"$q \\cdot k = {dot}$, $\\sqrt{{4}} = 2$, score $= {ans:g}$. The $\\sqrt{{d_k}}$ keeps scores from growing with dimension, "
                   "which would push softmax into saturation.", "Dot product, divided by the square root of the dimension.")


def linear_layer_params(rng):
    i, o = rng.choice([128, 256, 512, 768, 1024]), rng.choice([10, 64, 256, 3072])
    ans = i * o + o
    return Problem("parameter-count", f"How many trainable parameters does `nn.Linear({i}, {o})` (with bias) have?", ans, 1e-6,
                   f"Weight ${o}\\times{i} = {i * o}$ plus bias ${o}$: ${ans}$.", "Weights plus one bias per output.")


def lora_params(rng):
    d_in, d_out, r = rng.choice([768, 1024, 4096]), rng.choice([768, 1024, 4096]), rng.choice([4, 8, 16])
    ans = r * (d_in + d_out)
    return Problem("lora-params", f"LoRA adapts a frozen ${d_out}\\times{d_in}$ weight with $\\Delta W = BA$, $B \\in \\mathbb{{R}}^{{{d_out}\\times r}}$, "
                   f"$A \\in \\mathbb{{R}}^{{r\\times{d_in}}}$, rank $r = {r}$. How many trainable parameters does the adapter add?", ans, 1e-6,
                   f"$r(d_{{in}} + d_{{out}}) = {r}({d_in} + {d_out}) = {ans}$, versus ${d_in * d_out}$ for full fine-tuning "
                   f"({100 * ans / (d_in * d_out):.2f}%).", "Count the entries of A and B.")


def regression_slope(rng):
    xs = [0, 1, 2, 3]
    m, c = rng.randint(-2, 3), rng.randint(-2, 3)
    noise = rng.choice([[0, 1, -1, 0], [1, -1, -1, 1], [0, 0, 1, -1], [-1, 1, 0, 0]])
    ys = [m * x + c + e for x, e in zip(xs, noise)]
    xb, yb = sum(xs) / 4, sum(ys) / 4
    ans = sum((x - xb) * (y - yb) for x, y in zip(xs, ys)) / sum((x - xb) ** 2 for x in xs)
    return Problem("regression-slope", "Fit $y = wx + b$ by least squares to the points " + ", ".join(f"$({x}, {y})$" for x, y in zip(xs, ys))
                   + ". What is the slope $w$? Round to 3 decimals.", ans, 2e-3,
                   f"$w = \\frac{{\\sum (x_i-\\bar x)(y_i-\\bar y)}}{{\\sum (x_i - \\bar x)^2}}$ with $\\bar x = {xb:g}$, $\\bar y = {yb:g}$: $w \\approx {_r(ans)}$. "
                   "This is the closed form that gradient descent on MSE converges to.", "Covariance of x and y divided by the variance of x.")


GENERATORS: dict[str, tuple[str, Callable[[random.Random], Problem]]] = {
    "dot-product": ("Linear algebra", dot_product), "vector-norm": ("Linear algebra", vector_norm),
    "cosine-similarity": ("Linear algebra", cosine_similarity), "matmul-entry": ("Linear algebra", matmul_entry),
    "matmul-cost": ("Linear algebra", matmul_cost), "determinant": ("Linear algebra", determinant_2x2),
    "eigenvalues": ("Linear algebra", eigen_symmetric),
    "derivative": ("Calculus", derivative_poly), "chain-rule": ("Calculus", chain_rule),
    "partial-derivative": ("Calculus", partial_derivative), "sigmoid": ("Calculus", sigmoid_derivative),
    "gradient-descent": ("Calculus", gradient_descent_step),
    "bayes-rule": ("Probability", bayes_rule), "expectation": ("Probability", expectation), "variance": ("Probability", variance),
    "entropy": ("Probability", entropy_bits), "kl-divergence": ("Probability", kl_divergence),
    "conditional-probability": ("Probability", conditional_probability),
    "softmax": ("ML formulas", softmax), "cross-entropy": ("ML formulas", cross_entropy), "mse": ("ML formulas", mse),
    "precision-recall": ("ML formulas", precision_recall_f1), "attention-score": ("ML formulas", attention_score),
    "parameter-count": ("ML formulas", linear_layer_params), "lora-params": ("ML formulas", lora_params),
    "regression-slope": ("ML formulas", regression_slope),
}
TOPICS = list(GENERATORS)


def problem(day: date, idx: int, topic: str) -> Problem:
    seed = int(hashlib.sha256(f"{day.isoformat()}:{idx}:{topic}".encode()).hexdigest()[:16], 16)
    return GENERATORS[topic][1](random.Random(seed))


def drill_topics(day: date, week_topics: list[str], review_topics: list[str], n: int = 5) -> list[str]:
    """n topics for the day: up to 2 review slots for recently MISSED topics, the rest cycle through this week's topics
    (rotated by weekday so each day leads with a different one). Unknown topic names are ignored."""
    week = [t for t in week_topics if t in GENERATORS] or TOPICS
    review = [t for t in dict.fromkeys(review_topics) if t in GENERATORS][:2]
    start = day.toordinal()
    fresh = [week[(start + i) % len(week)] for i in range(n - len(review))]
    return review + fresh


_FRACTION = re.compile(r"^\s*(-?\d+(?:\.\d+)?)\s*/\s*(-?\d+(?:\.\d+)?)\s*$")


def parse_answer(text: str) -> float | None:
    """Accepts '0.25', '-3', '1e-3', '1/4', '25%'. Returns None if unparseable."""
    t = (text or "").strip().replace(",", "").replace("−", "-")
    if not t:
        return None
    m = _FRACTION.match(t)
    try:
        if m:
            den = float(m.group(2))
            return None if den == 0 else float(m.group(1)) / den
        if t.endswith("%"):
            return float(t[:-1]) / 100
        v = float(t)
        return v if math.isfinite(v) else None
    except ValueError:
        return None


def is_correct(p: Problem, given: float) -> bool:
    return abs(given - p.answer) <= max(p.tol, 1e-9 * abs(p.answer))
